(5422161, 779772, 37444, '<td valign="top">Has anyone else ever said that looks like a bison?</td>', 'Has anyone else ever said that looks like a bison?', '2009-04-06 17:43:51.000000', NULL, 1),
(5422164, 779576, 101256, '<td valign="top">Total effect is great - unfortunately, the choice of colors in the font is a minor flaw - the yellow disappears into the white and isn''t distinctive enough to stand out against the stark background. Same with the yellow crayon - it disappears as compared to the others. If the yellow were changed, or a contrasting drop shadow used, it would be much more effective.</td>', 'Total effect is great - unfortunately, the choice of colors in the font is a minor flaw - the yellow disappears into the white and isn''t distinctive enough to stand out against the stark background. Same with the yellow crayon - it disappears as compared to the others. If the yellow were changed, or a contrasting drop shadow used, it would be much more effective.', '2009-04-06 17:44:20.000000', NULL, 1),
(5422168, 779484, 44611, '<td valign="top">Fab shot of Parliament, lovely light and colours.  Have to say that I''m not keen on the font you''ve useed for the postcard though; I think something a bit more traditional would have suited the image better.</td>', 'Fab shot of Parliament, lovely light and colours.  Have to say that I''m not keen on the font you''ve useed for the postcard though; I think something a bit more traditional would have suited the image better.', '2009-04-06 17:45:26.000000', NULL, 1),
(5422170, 779175, 37444, '<td valign="top">Topaz? I love the effect! 9</td>', 'Topaz? I love the effect! 9', '2009-04-06 17:45:56.000000', NULL, 1),
(5422171, 779497, 37444, '<td valign="top">So beautifully done - 10</td>', 'So beautifully done - 10', '2009-04-06 17:46:16.000000', NULL, 1),
(5422172, 779656, 37444, '<td valign="top">Love it! 9</td>', 'Love it! 9', '2009-04-06 17:46:25.000000', NULL, 1),
(5422175, 779473, 37444, '<td valign="top">beautiful scene - 9</td>', 'beautiful scene - 9', '2009-04-06 17:46:52.000000', NULL, 1),
(5422176, 779817, 101256, '<td valign="top">The drop light effect is very clever and the subject is properly illuminated. I like the DOF control. The font is perfectly placed and stands out. The highlights on the shell are a little distracting, but not so that they have a major impact on the overall image. Nice conept and good execution.</td>', 'The drop light effect is very clever and the subject is properly illuminated. I like the DOF control. The font is perfectly placed and stands out. The highlights on the shell are a little distracting, but not so that they have a major impact on the overall image. Nice conept and good execution.', '2009-04-06 17:47:07.000000', NULL, 1),
(5422177, 779502, 37444, '<td valign="top">nicely done - 8</td>', 'nicely done - 8', '2009-04-06 17:47:08.000000', NULL, 1),
(5422179, 779636, 44611, '<td valign="top">The lighting and colours here are stunning but, sadly, the subject of the image doesn''t excite me at all.  Good choice of font.</td>', 'The lighting and colours here are stunning but, sadly, the subject of the image doesn''t excite me at all.  Good choice of font.', '2009-04-06 17:48:11.000000', NULL, 1),
(5422181, 779806, 101256, '<td valign="top">The odd lighting and minor lens burp in the right hand upper corner do not make this a great image.  The concept is good, but much more eposure was needed to make the building stand out.</td>', 'The odd lighting and minor lens burp in the right hand upper corner do not make this a great image.  The concept is good, but much more eposure was needed to make the building stand out.', '2009-04-06 17:48:29.000000', NULL, 1),
(5422183, 779175, 44611, '<td valign="top">Terrific piece of photo art, but don''t see this as a postcard for anything.</td>', 'Terrific piece of photo art, but don''t see this as a postcard for anything.', '2009-04-06 17:49:14.000000', NULL, 1),
(5422185, 779771, 103032, '<td valign="top">The composition doesn''t work for me.  The wood railing and flower bed dominate the image.  If the POV was over to the right, maybe work the bear carvings into the image as a focal point with the lodge in the background maybe???<br/>I''m not getting the essence of Smoky Falls Lodge with this composition; I''m not enticed to visit.</td>', 'The composition doesn''t work for me.  The wood railing and flower bed dominate the image.  If the POV was over to the right, maybe work the bear carvings into the image as a focal point with the lodge in the background maybe???I''m not getting the essence of Smoky Falls Lodge with this composition; I''m not enticed to visit.', '2009-04-06 17:50:02.000000', NULL, 1),
(5422189, 779605, 101256, '<td valign="top">If this were sharper instead of the soft focus used, it would be outstanding. The clever use of light and shadow against the backdrop demonstrates the nature of one of the world''s most beautiful cities. Straight forward font with a subtle color works very well with this. Almost perfect.</td>', 'If this were sharper instead of the soft focus used, it would be outstanding. The clever use of light and shadow against the backdrop demonstrates the nature of one of the world''s most beautiful cities. Straight forward font with a subtle color works very well with this. Almost perfect.', '2009-04-06 17:51:08.000000', NULL, 1),
(5422191, 779200, 44611, '<td valign="top">One of my top picks for this challenge.  This has lovely colours, a great silhouette and the line leading my eye through the shot.  Good choice of font too.</td>', 'One of my top picks for this challenge.  This has lovely colours, a great silhouette and the line leading my eye through the shot.  Good choice of font too.', '2009-04-06 17:51:32.000000', NULL, 1),
(5422194, 779576, 44611, '<td valign="top">Great fun.  Good detail on the crayons.  Think the font could be clearer/larger.</td>', 'Great fun.  Good detail on the crayons.  Think the font could be clearer/larger.', '2009-04-06 17:52:17.000000', NULL, 1),
(5422196, 779350, 103032, '<td valign="top">Maybe its just me, but the tower looks like it''s leaning to the left.  Otherwise, its a nice classic university postcard image.</td>', 'Maybe its just me, but the tower looks like it''s leaning to the left.  Otherwise, its a nice classic university postcard image.', '2009-04-06 17:52:39.000000', NULL, 1),
(5422201, 779775, 101256, '<td valign="top">Very dramatic image - the sharp golden foreground slightly offset against the darker gorge is very pleasing to the eye and provides some tension which you don''t normally see in a post card. I''m not overly pleased with the drop shadow on the font - it would have worked much better without the drop shadow. Nice composition and effective use of light and space.</td>', 'Very dramatic image - the sharp golden foreground slightly offset against the darker gorge is very pleasing to the eye and provides some tension which you don''t normally see in a post card. I''m not overly pleased with the drop shadow on the font - it would have worked much better without the drop shadow. Nice composition and effective use of light and space.', '2009-04-06 17:53:30.000000', NULL, 1),
(5422210, 779137, 101256, '<td valign="top">This would have worked much better is the text had been placed in the huge blank white space. Also, the image isn''t the best as you lost the details of the cows face shooting into the light - you might have done better using a flash to retrieve some of the cow''s details. Having said that, I like what you tried to achieve here - it''s a heck of an idea just lacking in execution.</td>', 'This would have worked much better is the text had been placed in the huge blank white space. Also, the image isn''t the best as you lost the details of the cows face shooting into the light - you might have done better using a flash to retrieve some of the cow''s details. Having said that, I like what you tried to achieve here - it''s a heck of an idea just lacking in execution.', '2009-04-06 17:55:34.000000', NULL, 1),
(5422229, 779577, 103032, '<td valign="top">Nice image.  I''m guessing a lot of post processing.  Compared to other night skyline images, I like how the buildings are lit up.  I like how you can see the buildings against the sky as opposed to being lost in the dark.  The only negative for me is that the clouds look odd, not quite normal/natural, but I can''t put my finger on it.  Overall a nice postcard image.</td>', 'Nice image.  I''m guessing a lot of post processing.  Compared to other night skyline images, I like how the buildings are lit up.  I like how you can see the buildings against the sky as opposed to being lost in the dark.  The only negative for me is that the clouds look odd, not quite normal/natural, but I can''t put my finger on it.  Overall a nice postcard image.', '2009-04-06 18:02:10.000000', NULL, 1),
(5422241, 779500, 103032, '<td valign="top">Wow, nice.  Brilliant colors of the sky, sand and water.  Pier buildings nicely illuminated.  I would go visit if I got this postcard.</td>', 'Wow, nice.  Brilliant colors of the sky, sand and water.  Pier buildings nicely illuminated.  I would go visit if I got this postcard.', '2009-04-06 18:05:11.000000', NULL, 1),
(5422258, 779685, 103032, '<td valign="top">I don''t know if anything could have been done about this, but his right eye being partially covered is distracting.  Otherwise a nice image.</td>', 'I don''t know if anything could have been done about this, but his right eye being partially covered is distracting.  Otherwise a nice image.', '2009-04-06 18:08:51.000000', NULL, 1),
(5422267, 779600, 103032, '<td valign="top">Nice image, but for a postcard I would like a color image. IMO.</td>', 'Nice image, but for a postcard I would like a color image. IMO.', '2009-04-06 18:10:54.000000', NULL, 1),
(5422281, 779798, 45857, '<td valign="top">nice picture , but I have mixed emotions about it as a postcard</td>', 'nice picture , but I have mixed emotions about it as a postcard', '2009-04-06 18:14:37.000000', NULL, 1),
(5422282, 779512, 103032, '<td valign="top">Nice image, I guess technically very well done, but if I got this postcard, I wouldn''t know what to think... just my 2 cents.</td>', 'Nice image, I guess technically very well done, but if I got this postcard, I wouldn''t know what to think... just my 2 cents.', '2009-04-06 18:14:41.000000', NULL, 1),
(5422286, 778696, 39427, '<td valign="top">cool view, one that isn''t typical of the NY skyline... I must say though that either camera shake or something has made the details a bitty murky and the image could be sharper... gl</td>', 'cool view, one that isn''t typical of the NY skyline... I must say though that either camera shake or something has made the details a bitty murky and the image could be sharper... gl', '2009-04-06 18:16:02.000000', NULL, 1),
(5422290, 779662, 45857, '<td valign="top">I don''t know much about Tioga county, but I feel I could get lost there, much like your goose has. Good choice of font.</td>', 'I don''t know much about Tioga county, but I feel I could get lost there, much like your goose has. Good choice of font.', '2009-04-06 18:16:49.000000', NULL, 1),
(5422299, 779766, 103032, '<td valign="top">A classic university image, but it would have been better if you tilted the central corner line absolutely vertical. IMO</td>', 'A classic university image, but it would have been better if you tilted the central corner line absolutely vertical. IMO', '2009-04-06 18:18:19.000000', NULL, 1),
(5422303, 779381, 45857, '<td valign="top">good shot, but that shadow drop font wasn''t a good choice.</td>', 'good shot, but that shadow drop font wasn''t a good choice.', '2009-04-06 18:19:11.000000', NULL, 1),
(5422310, 778609, 103032, '<td valign="top">Classic.</td>', 'Classic.', '2009-04-06 18:20:17.000000', NULL, 1),
(5422318, 779806, 103032, '<td valign="top">Too dark.</td>', 'Too dark.', '2009-04-06 18:22:11.000000', NULL, 1),
(5422320, 779700, 45857, '<td valign="top">Good shot, works well as a postcard, but the color of your font gets lost in the image.</td>', 'Good shot, works well as a postcard, but the color of your font gets lost in the image.', '2009-04-06 18:22:32.000000', NULL, 1),
(5422337, 778696, 103032, '<td valign="top">I like this postcard.  Its unique in that the building in the skyline are B&amp;W but one building has color.  An interesting spin on the skyline.  Well done.</td>', 'I like this postcard.  Its unique in that the building in the skyline are B&W but one building has color.  An interesting spin on the skyline.  Well done.', '2009-04-06 18:26:36.000000', NULL, 1),
(5422340, 779671, 101256, '<td valign="top">Very nice image and the complimentary font and color are perfect. A very different concept than the submissions so far - out of the box thinking and the author has done a great job conveying the impression of longing. Well done.</td>', 'Very nice image and the complimentary font and color are perfect. A very different concept than the submissions so far - out of the box thinking and the author has done a great job conveying the impression of longing. Well done.', '2009-04-06 18:27:21.000000', NULL, 1),
(5422349, 779717, 45857, '<td valign="top">This really says "Virginia is for Lovers" to me    :)<br/>As a picture , I do like the detail of the fence<br/>good job doing your best with the weather you get.</td>', 'This really says "Virginia is for Lovers" to me    :)As a picture , I do like the detail of the fencegood job doing your best with the weather you get.', '2009-04-06 18:28:41.000000', NULL, 1),
(5422353, 778734, 101256, '<td valign="top">The major problem with winter images is they can be either stark or busy - this is a combination of the two. The white space in this image doesn''t do it any favors, but it does impart a sense of space which is a plus. The combination of large blank space top and bottom aren''t helpful either.</td>', 'The major problem with winter images is they can be either stark or busy - this is a combination of the two. The white space in this image doesn''t do it any favors, but it does impart a sense of space which is a plus. The combination of large blank space top and bottom aren''t helpful either.', '2009-04-06 18:29:28.000000', NULL, 1),
(5422359, 779772, 80104, '<td valign="top">This is a neat one.  Got engaged there.  Proposed on the mountain with the gondola.  Not sure if that''s the one since it was the summer.</td>', 'This is a neat one.  Got engaged there.  Proposed on the mountain with the gondola.  Not sure if that''s the one since it was the summer.', '2009-04-06 18:30:37.000000', NULL, 1),
(5422361, 779244, 103032, '<td valign="top">Nice focal point on the sculpture and the nicely illuminated skyline. Colors are nice.  I think you could have eliminated the text on the bottom and put the text in the dead space in the upper right sky.  IMO</td>', 'Nice focal point on the sculpture and the nicely illuminated skyline. Colors are nice.  I think you could have eliminated the text on the bottom and put the text in the dead space in the upper right sky.  IMO', '2009-04-06 18:31:23.000000', NULL, 1),
(5422364, 779731, 101256, '<td valign="top">A very good action image nice and sharp with plenty of color.  The font is a good selection, but the black isn''t the best choice. The overall impact is effective and demonstrates the nature of racing. Nice composition.</td>', 'A very good action image nice and sharp with plenty of color.  The font is a good selection, but the black isn''t the best choice. The overall impact is effective and demonstrates the nature of racing. Nice composition.', '2009-04-06 18:31:58.000000', NULL, 1),
(5422365, 779649, 80104, '<td valign="top">Nice concept.  Wished there was a bit more contrast.  Levels or an unsharp mask to remove a bit of fog possibly?  7 because the concept is great.</td>', 'Nice concept.  Wished there was a bit more contrast.  Levels or an unsharp mask to remove a bit of fog possibly?  7 because the concept is great.', '2009-04-06 18:32:04.000000', NULL, 1),
(5422370, 779652, 45857, '<td valign="top">"Oh no, not hakari for supper again"   :)</td>', '"Oh no, not hakari for supper again"   :)', '2009-04-06 18:33:28.000000', NULL, 1),
(5422371, 779581, 101256, '<td valign="top">Perfect - the highlights are right on the edge, the colors are subdued complimenting the highlighted subject. I like the font selection and color - it could be a little larger, but not by much.</td>', 'Perfect - the highlights are right on the edge, the colors are subdued complimenting the highlighted subject. I like the font selection and color - it could be a little larger, but not by much.', '2009-04-06 18:33:28.000000', NULL, 1),
(5422375, 779381, 101256, '<td valign="top">And just in time for opening day!!  I really like the embossed effect of the font - it''s of proper size and spacing and fits the overall composition. Well done.</td>', 'And just in time for opening day!!  I really like the embossed effect of the font - it''s of proper size and spacing and fits the overall composition. Well done.', '2009-04-06 18:34:58.000000', NULL, 1),
(5422377, 779067, 45857, '<td valign="top">Very period<br/>Aging the white border would have been a good touch</td>', 'Very periodAging the white border would have been a good touch', '2009-04-06 18:35:13.000000', NULL, 1),
(5422378, 779769, 103032, '<td valign="top">Wow, a toss up between this Niagara and the other one.  The multiple colors and more skyline work well.  I''d have to give this one a slight edge.  Nice job.</td>', 'Wow, a toss up between this Niagara and the other one.  The multiple colors and more skyline work well.  I''d have to give this one a slight edge.  Nice job.', '2009-04-06 18:35:51.000000', NULL, 1),
(5422380, 779038, 101256, '<td valign="top">A good solid commercial image and very good font selection and placement. Not over whelming in any sense. I''d like to see a little more detail of the shadow, but that relates to the lighting - this might have worked better if taken early in the morning with softer light. Nicely done.</td>', 'A good solid commercial image and very good font selection and placement. Not over whelming in any sense. I''d like to see a little more detail of the shadow, but that relates to the lighting - this might have worked better if taken early in the morning with softer light. Nicely done.', '2009-04-06 18:37:03.000000', NULL, 1),
(5422384, 779732, 103032, '<td valign="top">A perfect postcard. 10</td>', 'A perfect postcard. 10', '2009-04-06 18:39:30.000000', NULL, 1),
(5422386, 779632, 101256, '<td valign="top">I don''t know how to rate this because, as I understand them, the rules for this challenge did not allow for the addition of a canvas artistic filter. On the other hand it is a very effective image and concept. I''m not going to complain about it -  I like it.</td>', 'I don''t know how to rate this because, as I understand them, the rules for this challenge did not allow for the addition of a canvas artistic filter. On the other hand it is a very effective image and concept. I''m not going to complain about it -  I like it.', '2009-04-06 18:41:07.000000', NULL, 1),
(5422388, 779635, 101256, '<td valign="top">Simply perfect. This image has a elegance that is hard to describe - the very subtle blue shading imparts a sense of style and purpose. The whites are right on the edge which is a plus because it imparts a sense of depth and dimension. The simple font and placement work very well with the image. A very nice blend of concepts. Well done.</td>', 'Simply perfect. This image has a elegance that is hard to describe - the very subtle blue shading imparts a sense of style and purpose. The whites are right on the edge which is a plus because it imparts a sense of depth and dimension. The simple font and placement work very well with the image. A very nice blend of concepts. Well done.', '2009-04-06 18:43:37.000000', NULL, 1),
(5422390, 779333, 103032, '<td valign="top">The brown sky doesn''t make this an enticing place to visit.  The skyline building are nicely illuminated, but too much water and again the sky just looks smoggy.</td>', 'The brown sky doesn''t make this an enticing place to visit.  The skyline building are nicely illuminated, but too much water and again the sky just looks smoggy.', '2009-04-06 18:43:55.000000', NULL, 1),
(5422393, 779578, 101256, '<td valign="top">Like it - the slight fade in the colors towards the upper left is excellant and the sense of dimension is very complimentary to the image in extant. I like the way the author handled the font placement although it''s not the best choice.  Well done.</td>', 'Like it - the slight fade in the colors towards the upper left is excellant and the sense of dimension is very complimentary to the image in extant. I like the way the author handled the font placement although it''s not the best choice.  Well done.', '2009-04-06 18:45:08.000000', NULL, 1),
(5422394, 779529, 45857, '<td valign="top">Nice toning</td>', 'Nice toning', '2009-04-06 18:45:18.000000', NULL, 1),
(5422396, 779416, 80104, '<td valign="top">Love the lighting of this shot.  What a spectacle.  10</td>', 'Love the lighting of this shot.  What a spectacle.  10', '2009-04-06 18:46:52.000000', NULL, 1),
(5422398, 779497, 80104, '<td valign="top">What a great job.  Love the lighting.  Just about hypnotizing.  10</td>', 'What a great job.  Love the lighting.  Just about hypnotizing.  10', '2009-04-06 18:47:18.000000', NULL, 1),
(5422400, 779769, 80104, '<td valign="top">Boy I miss Niagara Falls.  Too bad no one took a shot of the Canadian Falls.  Love this one.  10</td>', 'Boy I miss Niagara Falls.  Too bad no one took a shot of the Canadian Falls.  Love this one.  10', '2009-04-06 18:47:53.000000', NULL, 1),
(5422401, 779823, 80104, '<td valign="top">Love the lighting you got out of this one.  There''s something mezmorizing about it.  9</td>', 'Love the lighting you got out of this one.  There''s something mezmorizing about it.  9', '2009-04-06 18:48:17.000000', NULL, 1),
(5422402, 779816, 103032, '<td valign="top">Looks a bit over exposed.  Too much halo around the Dome and the buildings.  I think a blue sky would have worked better.</td>', 'Looks a bit over exposed.  Too much halo around the Dome and the buildings.  I think a blue sky would have worked better.', '2009-04-06 18:48:19.000000', NULL, 1),
(5422403, 779244, 80104, '<td valign="top">Very well done.  The spitting statue is really cool.  Wish I was there.</td>', 'Very well done.  The spitting statue is really cool.  Wish I was there.', '2009-04-06 18:48:39.000000', NULL, 1),
(5422407, 779805, 80104, '<td valign="top">Nice shot.  Wish the lighting was a big more pronounced(color maybe).  Also might have been nicer cropped in a tad more.  8 for me</td>', 'Nice shot.  Wish the lighting was a big more pronounced(color maybe).  Also might have been nicer cropped in a tad more.  8 for me', '2009-04-06 18:49:17.000000', NULL, 1),
(5422409, 779508, 80104, '<td valign="top">Very well done.  Curious about the bluish light in the water.  Boat?</td>', 'Very well done.  Curious about the bluish light in the water.  Boat?', '2009-04-06 18:49:43.000000', NULL, 1),
(5422411, 779717, 80104, '<td valign="top">Although I didn''t give it a 10 this is probably my favorite image.  So simple yet perfect.  I have a similar site up here in Canada.  Wish I could get a sky to look like yours.  Nicely done. 9</td>', 'Although I didn''t give it a 10 this is probably my favorite image.  So simple yet perfect.  I have a similar site up here in Canada.  Wish I could get a sky to look like yours.  Nicely done. 9', '2009-04-06 18:50:29.000000', NULL, 1),
(5422412, 779704, 103032, '<td valign="top">Building''s falling to the left.  It might have helped if the vertical lines of building weren''t tilted.</td>', 'Building''s falling to the left.  It might have helped if the vertical lines of building weren''t tilted.', '2009-04-06 18:50:35.000000', NULL, 1),
(5422414, 779732, 80104, '<td valign="top">Nicely done.  Too bad you couldn''t get it a little later in the evening for more night/light contrast.</td>', 'Nicely done.  Too bad you couldn''t get it a little later in the evening for more night/light contrast.', '2009-04-06 18:50:56.000000', NULL, 1),
(5422416, 778969, 45857, '<td valign="top">Wow, how did you get your font crooked?<br/>Colors are good for a early Photochrome card.<br/>Your sentiment is very cute.</td>', 'Wow, how did you get your font crooked?Colors are good for a early Photochrome card.Your sentiment is very cute.', '2009-04-06 18:51:05.000000', NULL, 1),
(5422421, 779607, 80104, '<td valign="top">Nice shot.  You picked a very good spot to shoot.  Back trees look a little off but otherwise a very nice one.  8 for me</td>', 'Nice shot.  You picked a very good spot to shoot.  Back trees look a little off but otherwise a very nice one.  8 for me', '2009-04-06 18:51:32.000000', NULL, 1),
(5422423, 779786, 80104, '<td valign="top">Very well done with the lighting.  Love the reflefction off the water from the tall whitish building.</td>', 'Very well done with the lighting.  Love the reflefction off the water from the tall whitish building.', '2009-04-06 18:51:58.000000', NULL, 1),
(5422427, 779366, 80104, '<td valign="top">Nice shot.  Just got 10 centimeters of snow today after a beautiful day yesterday.  Thought Spring was here.  Oh well guess I have to wait a few more days/weeks for it to look like your shot.  Kind of sucks for picture taking when you''re between Winter and Summer and yet the buds aren''t out yet.</td>', 'Nice shot.  Just got 10 centimeters of snow today after a beautiful day yesterday.  Thought Spring was here.  Oh well guess I have to wait a few more days/weeks for it to look like your shot.  Kind of sucks for picture taking when you''re between Winter and Summer and yet the buds aren''t out yet.', '2009-04-06 18:52:52.000000', NULL, 1),
(5422428, 779788, 80104, '<td valign="top">Well done.  Not my favorite but a definite keeper.  Lighting is fantastic.  Maybe a bit more side coverage of the bridge.  Couple hundred yards to the right?</td>', 'Well done.  Not my favorite but a definite keeper.  Lighting is fantastic.  Maybe a bit more side coverage of the bridge.  Couple hundred yards to the right?', '2009-04-06 18:53:30.000000', NULL, 1),
(5422430, 779524, 80104, '<td valign="top">Love the coloring on this one.  The Bridge leads me to the archway building.</td>', 'Love the coloring on this one.  The Bridge leads me to the archway building.', '2009-04-06 18:53:55.000000', NULL, 1),
(5422431, 779175, 80104, '<td valign="top">All I can say is nice pic.  Very neat</td>', 'All I can say is nice pic.  Very neat', '2009-04-06 18:54:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5422434, 779632, 90387, '<td valign="top">This is really cool!  I like the picture itself, but the processing is great for the challenge.</td>', 'This is really cool!  I like the picture itself, but the processing is great for the challenge.', '2009-04-06 18:54:43.000000', NULL, 1),
(5422436, 779719, 80104, '<td valign="top">Well considering I live 3 hours from here it''s not like I haven''t seen the city before but it''s a pic that invites me to want to visit again.  Nicely done.</td>', 'Well considering I live 3 hours from here it''s not like I haven''t seen the city before but it''s a pic that invites me to want to visit again.  Nicely done.', '2009-04-06 18:54:48.000000', NULL, 1),
(5422438, 779482, 80104, '<td valign="top">This is a really nice conceptual photo.  Love the way your shot was captured.  Just about a drawing feel to it.</td>', 'This is a really nice conceptual photo.  Love the way your shot was captured.  Just about a drawing feel to it.', '2009-04-06 18:55:14.000000', NULL, 1),
(5422439, 779598, 80104, '<td valign="top">Nicely done.  Love the plants at the bottom right.</td>', 'Nicely done.  Love the plants at the bottom right.', '2009-04-06 18:55:37.000000', NULL, 1),
(5422441, 779800, 80104, '<td valign="top">This is a really nice shot. Originally gave it an 8 but after further review I really like it with color and all.</td>', 'This is a really nice shot. Originally gave it an 8 but after further review I really like it with color and all.', '2009-04-06 18:55:59.000000', NULL, 1),
(5422443, 779381, 80104, '<td valign="top">Nice point of view...  Well except for the bum and all LoL.  Well done.  Lighting looks terrific.</td>', 'Nice point of view...  Well except for the bum and all LoL.  Well done.  Lighting looks terrific.', '2009-04-06 18:56:40.000000', NULL, 1),
