(5422784, 779500, 31637, '<td valign="top">Vibrant image, would love to see some text though.</td>', 'Vibrant image, would love to see some text though.', '2009-04-06 21:24:17.000000', NULL, 1),
(5422785, 779790, 31637, '<td valign="top">Very popular composition, I recall a similar image in the last Postcard challenge, if it works it works! Nice shot, tones excellent in Bridge''s tower.</td>', 'Very popular composition, I recall a similar image in the last Postcard challenge, if it works it works! Nice shot, tones excellent in Bridge''s tower.', '2009-04-06 21:25:22.000000', NULL, 1),
(5422786, 779586, 31637, '<td valign="top">Could be sharper, nice composition.</td>', 'Could be sharper, nice composition.', '2009-04-06 21:25:38.000000', NULL, 1),
