(5423492, 779804, 86799, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2009-04-07 06:58:43.000000', NULL, 1),
(5423493, 778980, 57229, '<td valign="top">Love the title</td>', 'Love the title', '2009-04-07 07:02:02.000000', NULL, 1),
(5423496, 779807, 57229, '<td valign="top">A little too much fuzz on the water? Actually that''s the main feature, so it dips out as a postcard. Text doesn''t tell us where Philadelphia is.</td>', 'A little too much fuzz on the water? Actually that''s the main feature, so it dips out as a postcard. Text doesn''t tell us where Philadelphia is.', '2009-04-07 07:04:22.000000', NULL, 1),
