(5423501, 779244, 57229, '<td valign="top">Yepp - that''s a postcard - sell it.</td>', 'Yepp - that''s a postcard - sell it.', '2009-04-07 07:08:47.000000', NULL, 1),
(5423502, 779755, 57229, '<td valign="top">Tacky and fuzzy - what more could you ask of a postcard. Slam dunks the challenge.</td>', 'Tacky and fuzzy - what more could you ask of a postcard. Slam dunks the challenge.', '2009-04-07 07:09:58.000000', NULL, 1),
