(5423517, 779460, 57229, '<td valign="top">Neat shot but not a neat postcard - in my arrogant opinion (sorry about that). Without the text it''s anywhere - ok so the text takes care of that, but...</td>', 'Neat shot but not a neat postcard - in my arrogant opinion (sorry about that). Without the text it''s anywhere - ok so the text takes care of that, but...', '2009-04-07 07:23:59.000000', NULL, 1),
(5423518, 779662, 57229, '<td valign="top">I''ve never seen a public address system that looks like that. It''s probably a local thing.</td>', 'I''ve never seen a public address system that looks like that. It''s probably a local thing.', '2009-04-07 07:25:36.000000', NULL, 1),
(5423519, 779819, 57229, '<td valign="top">I wonder what it means. You''re not selling this to people who aren''t familiar with US postal cryptics.</td>', 'I wonder what it means. You''re not selling this to people who aren''t familiar with US postal cryptics.', '2009-04-07 07:30:50.000000', NULL, 1),
(5423520, 779823, 57229, '<td valign="top">I guess it is. Anyway, it says so on the postcard, well done.</td>', 'I guess it is. Anyway, it says so on the postcard, well done.', '2009-04-07 07:31:38.000000', NULL, 1),
(5423522, 779759, 57229, '<td valign="top">The text format is telling me this is the home of the brash and tateless, but I can believe that...</td>', 'The text format is telling me this is the home of the brash and tateless, but I can believe that...', '2009-04-07 07:33:17.000000', NULL, 1),
