(5423526, 779497, 27133, '<td valign="top">Outstanding....this should be the winner!</td>', 'Outstanding....this should be the winner!', '2009-04-07 07:37:38.000000', NULL, 1),
(5423527, 778696, 57229, '<td valign="top">Well, you succeeded in producing a shot that looks like a postcard. I guess NYC is pretty boring.</td>', 'Well, you succeeded in producing a shot that looks like a postcard. I guess NYC is pretty boring.', '2009-04-07 07:38:21.000000', NULL, 1),
(5423528, 779512, 57229, '<td valign="top">OK, postcards can be generic. V good picture and processing.</td>', 'OK, postcards can be generic. V good picture and processing.', '2009-04-07 07:39:13.000000', NULL, 1),
(5423530, 779484, 57229, '<td valign="top">Dorky text. Interesting moody capture of Westminster, but the text breaks the mood in addition to being unnecessary for such an easily recognised landmark. More picture points than postcard points then :)</td>', 'Dorky text. Interesting moody capture of Westminster, but the text breaks the mood in addition to being unnecessary for such an easily recognised landmark. More picture points than postcard points then :)', '2009-04-07 07:42:21.000000', NULL, 1),
(5423531, 779817, 57229, '<td valign="top">Why''s that Florida?</td>', 'Why''s that Florida?', '2009-04-07 07:42:58.000000', NULL, 1),
(5423532, 779616, 57229, '<td valign="top">Good idea. Print out hundreds and sell them on the street.</td>', 'Good idea. Print out hundreds and sell them on the street.', '2009-04-07 07:44:03.000000', NULL, 1),
(5423534, 779732, 57229, '<td valign="top">The father of Pittsburgh? Is there an alternative version to send to your ma? Great shot - neat touch with the wavy text on the river.</td>', 'The father of Pittsburgh? Is there an alternative version to send to your ma? Great shot - neat touch with the wavy text on the river.', '2009-04-07 07:45:49.000000', NULL, 1),
(5423536, 779667, 57229, '<td valign="top">Their mothers loved them too.</td>', 'Their mothers loved them too.', '2009-04-07 07:46:51.000000', NULL, 1),
(5423538, 779717, 57229, '<td valign="top">I''m sure it''s a local thing, understanding how this picture is from Virginia as opposed to anywhere, but I have the text to help me with that, eh?<br/>Very nice atmospherics.</td>', 'I''m sure it''s a local thing, understanding how this picture is from Virginia as opposed to anywhere, but I have the text to help me with that, eh?Very nice atmospherics.', '2009-04-07 07:49:20.000000', NULL, 1),
(5423539, 779814, 57229, '<td valign="top">Thanks for the text. Are you sure it isn''t really Iceland? Pretty pic - makes the challenge and then some.</td>', 'Thanks for the text. Are you sure it isn''t really Iceland? Pretty pic - makes the challenge and then some.', '2009-04-07 07:50:47.000000', NULL, 1),
(5423541, 779700, 57229, '<td valign="top">Doesn''t look very nice. Good thing I''m not paying the architect, eh? The text gets a bit lost in there.</td>', 'Doesn''t look very nice. Good thing I''m not paying the architect, eh? The text gets a bit lost in there.', '2009-04-07 07:52:47.000000', NULL, 1),
(5423542, 779775, 57229, '<td valign="top">Looking good. Works for the challenge and everything -</td>', 'Looking good. Works for the challenge and everything -', '2009-04-07 07:55:42.000000', NULL, 1),
(5423543, 779640, 57229, '<td valign="top">Looks like the Yorkshire moors with snow.</td>', 'Looks like the Yorkshire moors with snow.', '2009-04-07 07:56:33.000000', NULL, 1),
(5423545, 779470, 57229, '<td valign="top">Nice with all those dorics touching the top - maybe some border might have helped there too. I don''t actually know where I am ...</td>', 'Nice with all those dorics touching the top - maybe some border might have helped there too. I don''t actually know where I am ...', '2009-04-07 07:58:49.000000', NULL, 1);
