(5423546, 779636, 57229, '<td valign="top">...and the vampire?</td>', '...and the vampire?', '2009-04-07 07:59:15.000000', NULL, 1),
(5423547, 779327, 57229, '<td valign="top">Very nice picture. Postcard? Hmm...</td>', 'Very nice picture. Postcard? Hmm...', '2009-04-07 07:59:52.000000', NULL, 1),
(5423548, 779800, 57229, '<td valign="top">I believe you - don''t know what it means though. Must be in the US, because that''s where people would presume you know and not bother to explain.</td>', 'I believe you - don''t know what it means though. Must be in the US, because that''s where people would presume you know and not bother to explain.', '2009-04-07 08:01:05.000000', NULL, 1),
(5423549, 779523, 57229, '<td valign="top">Damn, wait till Haile gets back and see this.<br/> <br/>That was a joke, this is a good postcard.</td>', 'Damn, wait till Haile gets back and see this. That was a joke, this is a good postcard.', '2009-04-07 08:02:01.000000', NULL, 1),
(5423552, 779674, 57229, '<td valign="top">This probably makes sense to people who know what it is and where it is and why anyone would want to take a picture or buy a postcard of it.</td>', 'This probably makes sense to people who know what it is and where it is and why anyone would want to take a picture or buy a postcard of it.', '2009-04-07 08:06:22.000000', NULL, 1),
(5423554, 778060, 57229, '<td valign="top">The title should be the text, instead of that dumb logo. Great shot.</td>', 'The title should be the text, instead of that dumb logo. Great shot.', '2009-04-07 08:07:50.000000', NULL, 1),
(5423556, 779320, 57229, '<td valign="top">That''s somewhere in North America isn''t it? Nice snow shot. Pity about the people. The text is useful as information, but not pretty.</td>', 'That''s somewhere in North America isn''t it? Nice snow shot. Pity about the people. The text is useful as information, but not pretty.', '2009-04-07 08:09:57.000000', NULL, 1),
(5423557, 779749, 57229, '<td valign="top">Can these people tell you what the possums call it when they play possum? This is a seriously postcard postcard - you shall be rewarded.</td>', 'Can these people tell you what the possums call it when they play possum? This is a seriously postcard postcard - you shall be rewarded.', '2009-04-07 08:12:16.000000', NULL, 1),
(5423575, 779381, 57229, '<td valign="top">If ever one should doubt the collective insanity...</td>', 'If ever one should doubt the collective insanity...', '2009-04-07 08:33:03.000000', NULL, 1),
(5423576, 779774, 57229, '<td valign="top">Sad. No doubt there''s a local market...</td>', 'Sad. No doubt there''s a local market...', '2009-04-07 08:33:33.000000', NULL, 1),
(5423579, 779600, 57229, '<td valign="top">I think a visitor might buy this, because it resonates with the place.</td>', 'I think a visitor might buy this, because it resonates with the place.', '2009-04-07 08:38:58.000000', NULL, 1),
(5423580, 778609, 57229, '<td valign="top">That''s a postcard.</td>', 'That''s a postcard.', '2009-04-07 08:39:28.000000', NULL, 1),
(5423582, 779718, 57229, '<td valign="top">I''m glad you put the text in there, because I wouldn''t have known :) Good entry.</td>', 'I''m glad you put the text in there, because I wouldn''t have known :) Good entry.', '2009-04-07 08:40:26.000000', NULL, 1),
