(5429246, 779719, 79720, '<td valign="top">Not voting, only commenting:<br/> <br/>TDot! Looks like from Ward''s Island...probably the same spot as my only ribbon, the little beach just off the Ferry Dock?</td>', 'Not voting, only commenting: TDot! Looks like from Ward''s Island...probably the same spot as my only ribbon, the little beach just off the Ferry Dock?', '2009-04-09 12:49:42.000000', NULL, 1),
(5429247, 779274, 83313, '<td valign="top">A nice enough scene, but it''s coming off to me more like a good snapshot than something to advertise this place. You also could have cloned out that red SUV under the advanced ruleset, and that may have helped a little. Mostly I think it just could benefit from a little more massaging in post processing.</td>', 'A nice enough scene, but it''s coming off to me more like a good snapshot than something to advertise this place. You also could have cloned out that red SUV under the advanced ruleset, and that may have helped a little. Mostly I think it just could benefit from a little more massaging in post processing.', '2009-04-09 12:50:00.000000', NULL, 1),
(5429249, 779823, 79720, '<td valign="top">Not voting, only commenting:<br/> <br/>Nice exposure, composition. I like the movement in the trees.</td>', 'Not voting, only commenting: Nice exposure, composition. I like the movement in the trees.', '2009-04-09 12:50:40.000000', NULL, 1),
(5429252, 779040, 79720, '<td valign="top">Not voting, only commenting:<br/> <br/><img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=89940" rel="nofollow" target="_blank">Moose408</a>? Based on the Flora entry from almost that same vantage point.</td>', 'Not voting, only commenting:  Moose408? Based on the Flora entry from almost that same vantage point.', '2009-04-09 12:52:36.000000', NULL, 1),
