(5429960, 779596, 79720, '<td valign="top">Not voting, just commenting:<br/> <br/>Stunning capture, this would make a brilliant postcard. I expect to see this on the front page.</td>', 'Not voting, just commenting: Stunning capture, this would make a brilliant postcard. I expect to see this on the front page.', '2009-04-09 22:15:18.000000', NULL, 1),
(5429987, 779652, 37845, '<td valign="top">I love the tongue in cheek approach you took to this. Not a flashy post card at all, but if I were to buy a post card, this is the type I would buy. 7 for now, but I will likely be back to bump this up a bit more.</td>', 'I love the tongue in cheek approach you took to this. Not a flashy post card at all, but if I were to buy a post card, this is the type I would buy. 7 for now, but I will likely be back to bump this up a bit more.', '2009-04-09 22:54:29.000000', NULL, 1),
(5430033, 779816, 31637, '<td valign="top">This is a fantastic postcard, I love the crop and/or fitting of the frame, its just filled with great architecture, my one complaint is the halo-ing around the dome...</td>', 'This is a fantastic postcard, I love the crop and/or fitting of the frame, its just filled with great architecture, my one complaint is the halo-ing around the dome...', '2009-04-09 23:51:44.000000', NULL, 1),
