(5430145, 779814, 56880, '<td valign="top">Nice smoothness of the water, it makes me miss California.  Excellent color.</td>', 'Nice smoothness of the water, it makes me miss California.  Excellent color.', '2009-04-10 01:42:25.000000', NULL, 1),
(5430149, 779740, 56880, '<td valign="top">The walkway is too centered for me; I''m led up the image but am almost rushed through to the other side, and I miss teh water and reflections along the way.<br/> <br/>The color of your text blends into the wood; the overall lack of contrast except for the far left makes it hard to read.</td>', 'The walkway is too centered for me; I''m led up the image but am almost rushed through to the other side, and I miss teh water and reflections along the way. The color of your text blends into the wood; the overall lack of contrast except for the far left makes it hard to read.', '2009-04-10 01:44:45.000000', NULL, 1),
(5430150, 779798, 56880, '<td valign="top">Nice text, but I''m missing the context for the starfish.</td>', 'Nice text, but I''m missing the context for the starfish.', '2009-04-10 01:45:24.000000', NULL, 1),
(5430153, 779701, 56880, '<td valign="top">The horizon is too centered, in my opinion.  Pushing it up a bit, and making the upper text horizontal, to mirror the text in the opposite corner, would help balance this shot.</td>', 'The horizon is too centered, in my opinion.  Pushing it up a bit, and making the upper text horizontal, to mirror the text in the opposite corner, would help balance this shot.', '2009-04-10 01:47:09.000000', NULL, 1),
(5430154, 779656, 56880, '<td valign="top">So much detail.  I might have centered the text, but that''s my only nitpick.</td>', 'So much detail.  I might have centered the text, but that''s my only nitpick.', '2009-04-10 01:48:26.000000', NULL, 1),
(5430155, 779366, 56880, '<td valign="top">The "Spring" text gets lost in the background; there isn''t enough contrast to make it pop out.</td>', 'The "Spring" text gets lost in the background; there isn''t enough contrast to make it pop out.', '2009-04-10 01:51:16.000000', NULL, 1),
