(5430610, 778684, 83313, '<td valign="top">Sorry, I have a couple of nitpicks. The starbursts have a bit of the jaggies, and I think your choice of using only a 600 pixel size instead of the 720 allowed may be part of the problem. More resolution allows for finer detail.</td>', 'Sorry, I have a couple of nitpicks. The starbursts have a bit of the jaggies, and I think your choice of using only a 600 pixel size instead of the 720 allowed may be part of the problem. More resolution allows for finer detail.', '2009-04-10 13:05:07.000000', NULL, 1),
(5430611, 779366, 83313, '<td valign="top">Not a subject I would normally consider as a postcard topic, but it''s a great floral shot. Great natural light and those score enhancing water droplets.</td>', 'Not a subject I would normally consider as a postcard topic, but it''s a great floral shot. Great natural light and those score enhancing water droplets.', '2009-04-10 13:06:50.000000', NULL, 1),
