(5430620, 779736, 83313, '<td valign="top">An udderly incredible shot! Curious what lens you used for this. My 300mm is just not enough for good moo shots.</td>', 'An udderly incredible shot! Curious what lens you used for this. My 300mm is just not enough for good moo shots.', '2009-04-10 13:13:03.000000', NULL, 1),
(5430622, 779656, 83313, '<td valign="top">Good b/w work. Nice and contrasty, but with plenty of detail. BTW, how did you manage to get a sunny day right when you needed one? I thought those were a special order item only.</td>', 'Good b/w work. Nice and contrasty, but with plenty of detail. BTW, how did you manage to get a sunny day right when you needed one? I thought those were a special order item only.', '2009-04-10 13:15:35.000000', NULL, 1),
