(5432047, 779667, 103229, '<td valign="top">very sharp and crisp, but the trees uneven are a little distracting and the people could be posed a little better</td>', 'very sharp and crisp, but the trees uneven are a little distracting and the people could be posed a little better', '2009-04-11 15:31:11.000000', NULL, 1),
(5432064, 779800, 44385, '<td valign="top">h</td>', 'h', '2009-04-11 15:59:46.000000', NULL, 1),
(5432065, 778609, 44385, '<td valign="top">h</td>', 'h', '2009-04-11 16:00:16.000000', NULL, 1),
(5432113, 778696, 83313, '<td valign="top">The lighting around that pier looks like bad haloing, but I do realize it is probably neon lights. Not sure I''m fond of the selective desat treatment, but I think that is a preference thing and you may get conflicting opinions on it.</td>', 'The lighting around that pier looks like bad haloing, but I do realize it is probably neon lights. Not sure I''m fond of the selective desat treatment, but I think that is a preference thing and you may get conflicting opinions on it.', '2009-04-11 17:06:10.000000', NULL, 1),
(5432116, 777965, 83313, '<td valign="top">Seems a little oversharp, but that''s appropriate for a postcard.</td>', 'Seems a little oversharp, but that''s appropriate for a postcard.', '2009-04-11 17:08:09.000000', NULL, 1),
(5432119, 779702, 83313, '<td valign="top">Just a great scene. Composition and crop leads my eye up to the mill quite nicely.</td>', 'Just a great scene. Composition and crop leads my eye up to the mill quite nicely.', '2009-04-11 17:09:01.000000', NULL, 1),
(5432121, 779632, 83313, '<td valign="top">Interesting choice of treatment. I can see what you were trying to achieve with it, though I am divided as to whether it works for this scene. The real problem may be trying to show off this interesting treatment with only 720 pixels.</td>', 'Interesting choice of treatment. I can see what you were trying to achieve with it, though I am divided as to whether it works for this scene. The real problem may be trying to show off this interesting treatment with only 720 pixels.', '2009-04-11 17:11:17.000000', NULL, 1),
(5432127, 779463, 83313, '<td valign="top">I think I have you beat in the tacky department. (No vote yet, just browsing)<br/> <br/>Added: Ok voting now. I can''t figure out why you might consider the Sydney Opera house to be tacky. Maybe it''s a Cliche shot, but if I visited Sydney, I would certainly take my share of pics of this place. Not as over-photographed as Toronto, however. But then, I believe 40% of DPC members live in Toronto.</td>', 'I think I have you beat in the tacky department. (No vote yet, just browsing) Added: Ok voting now. I can''t figure out why you might consider the Sydney Opera house to be tacky. Maybe it''s a Cliche shot, but if I visited Sydney, I would certainly take my share of pics of this place. Not as over-photographed as Toronto, however. But then, I believe 40% of DPC members live in Toronto.', '2009-04-11 17:18:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5432129, 779469, 83313, '<td valign="top">A very different approach, but perfectly suitable to the subject.</td>', 'A very different approach, but perfectly suitable to the subject.', '2009-04-11 17:18:41.000000', NULL, 1),
(5432131, 778422, 83313, '<td valign="top">I''m afraid I will have to be a nitpicker on this one. Seems a bit soft through the whole image, and the capitol building is in shadows, no doubt from a cloud passing overhead. I''ll bet a few minutes later you may have gotten the sun breaking through and hitting the capitol just right.</td>', 'I''m afraid I will have to be a nitpicker on this one. Seems a bit soft through the whole image, and the capitol building is in shadows, no doubt from a cloud passing overhead. I''ll bet a few minutes later you may have gotten the sun breaking through and hitting the capitol just right.', '2009-04-11 17:21:55.000000', NULL, 1),
(5432135, 779109, 83313, '<td valign="top">Nailed it! I think a touch more sun on the Washington monument would have helped, but it''s not totally buried in shadows. I think you were dealing with the same cloudy day as the previous D.C. photo I voted on.</td>', 'Nailed it! I think a touch more sun on the Washington monument would have helped, but it''s not totally buried in shadows. I think you were dealing with the same cloudy day as the previous D.C. photo I voted on.', '2009-04-11 17:24:11.000000', NULL, 1),
(5432136, 779715, 83313, '<td valign="top">I realize it is night, but perhaps a touch more brightness could bring out the scene and still look right. Other than that, It''s a pleasing and appropriate scene.</td>', 'I realize it is night, but perhaps a touch more brightness could bring out the scene and still look right. Other than that, It''s a pleasing and appropriate scene.', '2009-04-11 17:25:54.000000', NULL, 1),
(5432142, 778116, 83313, '<td valign="top">Reminds me of my own 4 years in the UK. I love this one and my only nitpick is you should have cloned out the overhead wires.</td>', 'Reminds me of my own 4 years in the UK. I love this one and my only nitpick is you should have cloned out the overhead wires.', '2009-04-11 17:27:07.000000', NULL, 1),
(5432144, 779526, 83313, '<td valign="top">Great backlighitng and I love how you handled the borders.</td>', 'Great backlighitng and I love how you handled the borders.', '2009-04-11 17:28:05.000000', NULL, 1),
(5432146, 779771, 83313, '<td valign="top">Nice scene, definitely something this lodge might have for it''s guests. One nitpick, however. I see a lot of jagginess, espcially around the bear and the red roofs. Not sure if it is oversharpening, or if it happened when scaling the shot down to 720 pixels.</td>', 'Nice scene, definitely something this lodge might have for it''s guests. One nitpick, however. I see a lot of jagginess, espcially around the bear and the red roofs. Not sure if it is oversharpening, or if it happened when scaling the shot down to 720 pixels.', '2009-04-11 17:30:30.000000', NULL, 1),
(5432151, 779596, 83313, '<td valign="top">Dang! I can''t find anything to nitpick about on this one. Drat! Exactly what I expect to see on the postcard rack. <br/> <br/>BTW, I''m seeing an awful lot of D.C. in this challenge, when did so many DPC members move to that area?</td>', 'Dang! I can''t find anything to nitpick about on this one. Drat! Exactly what I expect to see on the postcard rack.  BTW, I''m seeing an awful lot of D.C. in this challenge, when did so many DPC members move to that area?', '2009-04-11 17:33:48.000000', NULL, 1),
(5432154, 779587, 83313, '<td valign="top">A unique scene and great caption for it. Might need a little bump in colors and sharpening to make a killer shot out of it, though. If you decide to re-edit this one, I would love to see the result.</td>', 'A unique scene and great caption for it. Might need a little bump in colors and sharpening to make a killer shot out of it, though. If you decide to re-edit this one, I would love to see the result.', '2009-04-11 17:36:36.000000', NULL, 1),
(5432368, 779149, 31637, '<td valign="top">Great color and contrast, the image grain doesn''t work well for this image, try removing it. <br/> <br/>bumping up after 2nd viewing; the city fits perfectly under the bridge, cropped and filling the frame very nicely.</td>', 'Great color and contrast, the image grain doesn''t work well for this image, try removing it.  bumping up after 2nd viewing; the city fits perfectly under the bridge, cropped and filling the frame very nicely.', '2009-04-11 19:43:45.000000', NULL, 1),
